content.text:
/*
 * This is a manifest file that'll be compiled into application.css, which will include all the files
 * listed below.
 *
 * Any CSS (and SCSS, if configured) file within this directory, lib/assets/stylesheets, or plugin's
 * vendor/assets/stylesheets directory can be referenced here using a relative path.
 *
 *= require_tree .
 *= require_self
 */

:root {
  --todo-black: #1E1E1E;
  --todo-white: #FFFFFF;
  --todo-error: #CC3D3D;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  background: var(--todo-white);
  color: var(--todo-black);
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

button,
input {
  font: inherit;
}

.page-shell {
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  padding: 64px 24px;
}

.todo-panel {
  width: min(100%, 900px);
  overflow: hidden;
  background: var(--todo-white);
  border: 4px solid var(--todo-black);
  border-radius: 18px;
}

.todo-panel__header {
  padding: 18px 24px;
  background: var(--todo-black);
}

.todo-panel__header h1 {
  margin: 0;
  font-style: normal;
  font-weight: 700;
  font-size: 48px;
  line-height: 58px;
  text-align: center;
  color: var(--todo-white);
  vertical-align: middle;
}

.todo-panel__body {
  display: flex;
  flex-direction: column;
  gap: 28px;
  padding: 48px;
}

.inline-create-form {
  position: relative;
  width: 100%;
}

.text-input {
  width: 100%;
  min-height: 86px;
  padding: 18px 112px 18px 36px;
  border: 4px solid var(--todo-black);
  border-radius: 36px;
  color: var(--todo-black);
  font-weight: 400;
  font-size: 32px;
  line-height: 100%;
  text-align: left;
  outline: none;
}

.text-input::placeholder {
  color: rgba(30, 30, 30, 0.8);
  font-weight: 400;
  font-size: 32px;
  line-height: 100%;
  text-align: left;
}

.input-action {
  position: absolute;
  top: 50%;
  right: 0;
  width: 86px;
  height: 86px;
  padding: 0;
  border: 0;
  border-radius: 50%;
  transform: translateY(-50%);
  cursor: pointer;
}

.error-box {
  padding: 24px 32px;
  border: 4px solid var(--todo-error);
  border-radius: 36px;
  background: var(--todo-white);
  color: var(--todo-error);
}

.error-box p {
  margin: 0;
  color: var(--todo-error);
  font-size: 32px;
  line-height: 120%;
  text-align: center;
}

.error-box p + p {
  margin-top: 12px;
}

.items-list {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.empty-state {
  margin: 0;
  color: var(--todo-black);
  font-weight: 400;
  font-size: 32px;
  line-height: 100%;
  text-align: center;
  vertical-align: middle;
}

.todo-row {
  display: flex;
  align-items: center;
  gap: 20px;
  min-height: 64px;
}

.todo-row__text {
  flex: 1;
  color: var(--todo-black);
  font-weight: 400;
  font-size: 32px;
  line-height: 100%;
  vertical-align: middle;
  overflow-wrap: anywhere;
}

.todo-row__link {
  text-decoration: none;
}

.todo-row__link:hover,
.todo-row__link:focus {
  text-decoration: underline;
}

.todo-row__text--completed {
  text-decoration: line-through;
}

.button_to {
  margin: 0;
  line-height: 0;
}

.completion-button,
.icon-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  border: 0;
  background: transparent;
  cursor: pointer;
}

.completion-button,
.completion-button img,
.unchecked-circle {
  width: 48px;
  height: 48px;
}

.unchecked-circle {
  display: inline-block;
  border: 4px solid var(--todo-black);
  border-radius: 50%;
}

.icon-button,
.icon-button img {
  width: 64px;
  height: 64px;
}

.back-link {
  color: var(--todo-black);
  font-size: 24px;
  text-align: center;
}

@media (max-width: 640px) {
  .page-shell {
    padding: 24px 12px;
  }

  .todo-panel__header h1 {
    font-size: 36px;
    line-height: 44px;
  }

  .todo-panel__body {
    padding: 28px 18px;
  }

  .text-input,
  .text-input::placeholder,
  .todo-row__text,
  .empty-state,
  .error-box p {
    font-size: 24px;
  }
}

